local noticeId = 0
local function notify(text)
	noticeId = noticeId + 1
	local card = new("Frame", {
		Name = "Notice",
		Size = UDim2.new(1, 0, 0, 40),
		BackgroundColor3 = PANEL,
		BackgroundTransparency = 0.05,
		LayoutOrder = noticeId,
	}, noticeHolder)
	corner(card, 6)
	stroke(card, ACCENT, 1, 0.15)
	new("TextLabel", {
		Size = UDim2.new(1, -20, 1, 0),
		Position = UDim2.new(0, 10, 0, 0),
		BackgroundTransparency = 1,
		Text = tostring(text),
		TextColor3 = TEXT,
		Font = FONT_MED,
		TextSize = 12,
		TextWrapped = true,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
	}, card)
	task.spawn(function()
		task.wait(3)
		if card.Parent then
			TweenService:Create(card, TweenInfo.new(0.35), { BackgroundTransparency = 1 }):Play()
			for _, d in ipairs(card:GetDescendants()) do
				if d:IsA("TextLabel") then
					TweenService:Create(d, TweenInfo.new(0.35), { TextTransparency = 1 }):Play()
				elseif d:IsA("UIStroke") then
					TweenService:Create(d, TweenInfo.new(0.35), { Transparency = 1 }):Play()
				end
			end
			task.wait(0.35)
			card:Destroy()
		end
	end)
end

--------------------------------------------------------------------------------
--  script payload
--------------------------------------------------------------------------------

local GROUP_SRC = {}

local function loadGroup(gi)
	if GROUP_SRC[gi] then return GROUP_SRC[gi] end
	local b64 = GROUPS[gi]
	if not b64 then return nil end
	local data
	local ok, err = pcall(function()
		data = inflate(b64decode(b64))
	end)
	if not ok then
		notify("Unpack failed (group " .. gi .. "): " .. tostring(err))
		return nil
	end
	GROUPS[gi] = nil
	local scripts = {}
	local pos, n = 1, #data
	while pos + 3 <= n do
		local b1, b2, b3, b4 = string.byte(data, pos, pos + 3)
		local l = b1 * 16777216 + b2 * 65536 + b3 * 256 + b4
		pos = pos + 4
		scripts[#scripts + 1] = string.sub(data, pos, pos + l - 1)
		pos = pos + l
	end
	GROUP_SRC[gi] = scripts
	return scripts
end

local function executeGame(entry)
	local name, id, gi, si = entry[1], entry[2], entry[3], entry[4]
	if id and id ~= 0 and game.PlaceId ~= id then
		notify("Heads up: " .. name .. " is built for place " .. tostring(id))
	end
	local scripts = loadGroup(gi)
	if not scripts or not scripts[si] then
		notify("No data for " .. name)
		return false
	end
	local src = scripts[si]
	task.spawn(function()
		local fn, perr = loadstring(src, "Ouroboros/" .. name)
		if not fn then
			notify("Load error: " .. name .. " - " .. tostring(perr))
			return
		end
		local ok, rerr = pcall(fn)
		if not ok then
			notify("Error in " .. name .. " - " .. tostring(rerr))
		end
	end)
	return true
end

