local function makeToggle(parent, initial, callback)
	local state = initial and true or false
	local knobOff = UDim2.new(0, 3, 0.5, 0)
	local knobOn = UDim2.new(0, 27, 0.5, 0)
	local track = new("Frame", {
		Name = "Toggle",
		Size = UDim2.new(0, 46, 0, 22),
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -12, 0.5, 0),
		BackgroundColor3 = state and ACCENT or TRACK_OFF,
	}, parent)
	corner(track, 11)
	local knob = new("Frame", {
		Name = "Knob",
		Size = UDim2.new(0, 16, 0, 16),
		AnchorPoint = Vector2.new(0, 0.5),
		Position = state and knobOn or knobOff,
		BackgroundColor3 = Color3.new(1, 1, 1),
	}, track)
	corner(knob, 8)
	local btn = new("TextButton", {
		Name = "Hit",
		Size = UDim2.new(1, 0, 1, 0),
		BackgroundTransparency = 1,
		Text = "",
	}, track)

	local api = {}
	function api.set(v)
		v = v and true or false
		if api.state == v then return end
		api.state = v
		track.BackgroundColor3 = v and ACCENT or TRACK_OFF
		TweenService:Create(knob, TweenInfo.new(0.15), { Position = v and knobOn or knobOff }):Play()
		if callback then
			local ok, res = pcall(callback, v)
			if not ok then
				notify("Toggle error: " .. tostring(res))
			elseif v and res == false then
				api.state = false
				track.BackgroundColor3 = TRACK_OFF
				TweenService:Create(knob, TweenInfo.new(0.15), { Position = knobOff }):Play()
			end
		end
	end
	api.state = state
	btn.MouseButton1Click:Connect(function() api.set(not api.state) end)
	return api
end

local function makeValueBox(parent, default, minimum, maximum, onChanged)
	local box = new("TextBox", {
		Size = UDim2.new(0, 56, 0, 26),
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -66, 0.5, 0),
		BackgroundColor3 = BG,
		Text = tostring(default),
		TextColor3 = ACCENT,
		Font = FONT_MED,
		TextSize = 13,
		ClearTextOnFocus = false,
		TextXAlignment = Enum.TextXAlignment.Center,
	}, parent)
	corner(box, 5)
	stroke(box, ACCENT, 1, 0.55)
	box.FocusLost:Connect(function()
		local n = tonumber(box.Text)
		if not n then
			box.Text = tostring(default)
			return
		end
		n = math.clamp(math.floor(n), minimum, maximum)
		box.Text = tostring(n)
		if onChanged then onChanged(n) end
	end)
	return box
end

local function makeActionRow(parent, order, title, subtitle, opts)
	opts = opts or {}
	local row = new("Frame", {
		Size = UDim2.new(1, -8, 0, 50),
		BackgroundColor3 = ROW,
		LayoutOrder = order,
	}, parent)
	corner(row, 6)
	new("TextLabel", {
		Size = UDim2.new(1, -150, 0, 20),
		Position = UDim2.new(0, 12, 0, 7),
		BackgroundTransparency = 1,
		Text = title,
		TextColor3 = TEXT,
		Font = FONT_MED,
		TextSize = 14,
		TextXAlignment = Enum.TextXAlignment.Left,
	}, row)
	new("TextLabel", {
		Size = UDim2.new(1, -150, 0, 16),
		Position = UDim2.new(0, 12, 0, 27),
		BackgroundTransparency = 1,
		Text = subtitle or "",
		TextColor3 = SUB,
		Font = FONT,
		TextSize = 11,
		TextWrapped = true,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
	}, row)

	local valueBox
	if opts.value then
		valueBox = makeValueBox(row, opts.value.default, opts.value.min, opts.value.max, function(n)
			if opts.value.changed then opts.value.changed(n) end
		end)
	end
	local toggle = makeToggle(row, false, function(state)
		if opts.onToggle then
			local getVal
			if valueBox then
				getVal = function() return tonumber(valueBox.Text) or (opts.value and opts.value.default) end
			end
			opts.onToggle(state, getVal)
		end
	end)
	return { row = row, toggle = toggle, box = valueBox }
end

