-- ESP
local espActive = false
local espConns = {}
local function addESP(plr)
	if not espActive or plr == LocalPlayer then return end
	local ch = plr.Character
	if not ch then return end
	local hum = ch:FindFirstChildOfClass("Humanoid")
	local hrp = ch:FindFirstChild("HumanoidRootPart")
	if not hum or hum.Health <= 0 or not hrp then return end
	if ch:FindFirstChild("OuroESP") then return end
	new("Highlight", {
		Name = "OuroESP",
		FillColor = ACCENT,
		FillTransparency = 0.75,
		OutlineColor = ACCENT,
		OutlineTransparency = 0,
		DepthMode = Enum.HighlightDepthMode.AlwaysOnTop,
	}, ch)
	local bb = new("BillboardGui", {
		Name = "OuroESPName",
		Size = UDim2.new(0, 120, 0, 22),
		AlwaysOnTop = true,
		StudsOffset = Vector3.new(0, 3, 0),
	}, ch:FindFirstChild("Head") or ch)
	new("TextLabel", {
		Size = UDim2.new(1, 0, 1, 0),
		BackgroundTransparency = 1,
		Text = plr.Name,
		TextColor3 = ACCENT,
		TextStrokeTransparency = 0.4,
		Font = FONT_MED,
		TextSize = 13,
	}, bb)
end
local function clearESPChar(ch)
	if not ch then return end
	local h = ch:FindFirstChild("OuroESP")
	if h then h:Destroy() end
	local b = ch:FindFirstChild("OuroESPName")
	if b then b:Destroy() end
end
local function setESP(on)
	espActive = on
	if on then
		local function trackPlayer(plr)
			addESP(plr)
			table.insert(espConns, track(plr.CharacterAdded:Connect(function()
				task.wait(0.6)
				addESP(plr)
			end)))
		end
		for _, plr in ipairs(Players:GetPlayers()) do trackPlayer(plr) end
		table.insert(espConns, track(Players.PlayerAdded:Connect(trackPlayer)))
		table.insert(espConns, track(Players.PlayerRemoving:Connect(function(plr)
			if plr.Character then clearESPChar(plr.Character) end
		end)))
		notify("ESP enabled")
	else
		for _, c in ipairs(espConns) do pcall(function() c:Disconnect() end) end
		espConns = {}
		for _, plr in ipairs(Players:GetPlayers()) do
			if plr.Character then clearESPChar(plr.Character) end
		end
		notify("ESP disabled")
	end
end

-- FPS Boost
local fpsSaved = nil
local function setFPS(on)
	local terrain = workspace.Terrain
	if on then
		fpsSaved = { effects = {}, atm = {}, clouds = {} }
		fpsSaved.shadows = Lighting.GlobalShadows
		fpsSaved.fogStart = Lighting.FogStart
		fpsSaved.fogEnd = Lighting.FogEnd
		fpsSaved.brightness = Lighting.Brightness
		fpsSaved.water = {
			wave = terrain.WaterWaveSize,
			speed = terrain.WaterWaveSpeed,
			refl = terrain.WaterReflectance,
			transp = terrain.WaterTransparency,
		}
		for _, c in ipairs(Lighting:GetChildren()) do
			if c:IsA("PostEffect") then
				fpsSaved.effects[c] = c.Enabled
				c.Enabled = false
			elseif c:IsA("Atmosphere") then
				fpsSaved.atm[c] = { Density = c.Density, Haze = c.Haze }
				c.Density = 0
				c.Haze = 0
			end
		end
		for _, c in ipairs(terrain:GetChildren()) do
			if c:IsA("Clouds") then
				fpsSaved.clouds[c] = { Density = c.Density, Cover = c.Cover }
				c.Density = 0
				c.Cover = 0
			end
		end
		Lighting.GlobalShadows = false
		Lighting.FogEnd = 100000
		Lighting.Brightness = 2
		terrain.WaterWaveSize = 0
		terrain.WaterWaveSpeed = 0
		terrain.WaterReflectance = 0
		terrain.WaterTransparency = 1
		pcall(function() fpsSaved.quality = settings().Rendering.QualityLevel end)
		pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
		pcall(function() if setfpscap then setfpscap(60) end end)
		notify("FPS Boost enabled")
	else
		if fpsSaved then
			Lighting.GlobalShadows = fpsSaved.shadows
			Lighting.FogStart = fpsSaved.fogStart
			Lighting.FogEnd = fpsSaved.fogEnd
			Lighting.Brightness = fpsSaved.brightness
			for c, en in pairs(fpsSaved.effects) do pcall(function() c.Enabled = en end) end
			for c, v in pairs(fpsSaved.atm) do
				pcall(function()
					c.Density = v.Density
					c.Haze = v.Haze
				end)
			end
			for c, v in pairs(fpsSaved.clouds) do
				pcall(function()
					c.Density = v.Density
					c.Cover = v.Cover
				end)
			end
			terrain.WaterWaveSize = fpsSaved.water.wave
			terrain.WaterWaveSpeed = fpsSaved.water.speed
			terrain.WaterReflectance = fpsSaved.water.refl
			terrain.WaterTransparency = fpsSaved.water.transp
			if fpsSaved.quality then
				pcall(function() settings().Rendering.QualityLevel = fpsSaved.quality end)
			end
			fpsSaved = nil
		end
		pcall(function() if setfpscap then setfpscap(0) end end)
		notify("FPS Boost disabled")
	end
end

-- Gray Sky
local graySaved = nil
local function setGray(on)
	local terrain = workspace.Terrain
	if on then
		graySaved = { removed = {} }
		graySaved.fogColor = Lighting.FogColor
		graySaved.fogStart = Lighting.FogStart
		graySaved.fogEnd = Lighting.FogEnd
		graySaved.ambient = Lighting.Ambient
		graySaved.outdoor = Lighting.OutdoorAmbient
		graySaved.brightness = Lighting.Brightness
		for _, c in ipairs(Lighting:GetChildren()) do
			if c:IsA("Sky") or c:IsA("Atmosphere") then
				graySaved.removed[#graySaved.removed + 1] = { obj = c, parent = c.Parent }
				c.Parent = nil
			end
		end
		for _, c in ipairs(terrain:GetChildren()) do
			if c:IsA("Clouds") then
				graySaved.removed[#graySaved.removed + 1] = { obj = c, parent = c.Parent }
				c.Parent = nil
			end
		end
		Lighting.FogColor = Color3.fromRGB(150, 150, 152)
		Lighting.FogStart = 0
		Lighting.FogEnd = 100000
		Lighting.Ambient = Color3.fromRGB(150, 150, 152)
		Lighting.OutdoorAmbient = Color3.fromRGB(150, 150, 152)
		Lighting.Brightness = 2
		graySaved.cc = new("ColorCorrectionEffect", {
			Name = "OuroGrayFilter",
			Saturation = -1,
			Contrast = 0.1,
			Brightness = 0.02,
			TintColor = Color3.fromRGB(205, 208, 214),
		}, Lighting)
		notify("Gray Sky enabled")
	else
		if graySaved then
			for _, e in ipairs(graySaved.removed) do pcall(function() e.obj.Parent = e.parent end) end
			if graySaved.cc then graySaved.cc:Destroy() end
			Lighting.FogColor = graySaved.fogColor
			Lighting.FogStart = graySaved.fogStart
			Lighting.FogEnd = graySaved.fogEnd
			Lighting.Ambient = graySaved.ambient
			Lighting.OutdoorAmbient = graySaved.outdoor
			Lighting.Brightness = graySaved.brightness
			graySaved = nil
		end
		notify("Gray Sky disabled")
	end
end

-- Infinite Yield
local function setIY(on)
	if on then
		notify("Loading Infinite Yield ...")
		task.spawn(function()
			local ok, err = pcall(function()
				loadstring(game:HttpGet("https://raw.githubusercontent.com/EdgeIY/infiniteyield/master/source"))()
			end)
			if not ok then notify("Infinite Yield failed: " .. tostring(err)) end
		end)
	else
		pcall(function()
			local cg = game:GetService("CoreGui")
			local g = cg:FindFirstChild("Infinite Yield")
			if g then g:Destroy() end
		end)
		notify("Infinite Yield closed")
	end
end

-- Aimbot
local aimConn = nil
local AIM_FOV = 140
local AIM_SMOOTH = 0.35
local function setAimbot(on)
	if on then
		aimConn = track(RunService.RenderStepped:Connect(function()
			local cam = workspace.CurrentCamera
			if not cam then return end
			local mouse = UserInputService:GetMouseLocation()
			local best, bestScore = nil, AIM_FOV
			for _, plr in ipairs(Players:GetPlayers()) do
				if plr ~= LocalPlayer and plr.Character then
					local hum = plr.Character:FindFirstChildOfClass("Humanoid")
					local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
					if hum and hum.Health > 0 and hrp then
						local pos, onScreen = cam:WorldToViewportPoint(hrp.Position)
						if onScreen then
							local d = (Vector2.new(pos.X, pos.Y) - mouse).Magnitude
							if d < bestScore then
								local params = RaycastParams.new()
								params.FilterType = Enum.RaycastFilterType.Exclude
								params.FilterDescendantsInstances = { LocalPlayer.Character }
								local hit = workspace:Raycast(cam.CFrame.Position, (hrp.Position - cam.CFrame.Position).Unit * 600, params)
								if not hit or hit.Instance:IsDescendantOf(plr.Character) then
									bestScore = d
									best = hrp.Position
								end
							end
						end
					end
				end
			end
			if best then
				cam.CFrame = cam.CFrame:Lerp(CFrame.lookAt(cam.CFrame.Position, best), AIM_SMOOTH)
			end
		end))
		notify("Aimbot enabled")
	else
		if aimConn then
			aimConn:Disconnect()
			aimConn = nil
		end
		notify("Aimbot disabled")
	end
end

-- Fly
local flyConn = nil
local flyParts = nil
local FLY_SPEED = 60
local function setFly(on)
	local hrp = getChar() and getChar():FindFirstChild("HumanoidRootPart")
	if on then
		if not hrp then
			notify("Fly needs a spawned character")
			return false
		end
		local bv = new("BodyVelocity", {
			MaxForce = Vector3.new(9e9, 9e9, 9e9),
			P = 1250,
			Velocity = Vector3.zero,
		}, hrp)
		local bg = new("BodyGyro", {
			MaxTorque = Vector3.new(9e9, 9e9, 9e9),
			P = 90000,
			D = 5000,
			CFrame = hrp.CFrame,
		}, hrp)
		flyParts = { bv, bg }
		flyConn = track(RunService.RenderStepped:Connect(function()
			if not flyParts or not flyParts[1].Parent then return end
			local cam = workspace.CurrentCamera
			flyParts[2].CFrame = cam.CFrame
			local dir = Vector3.zero
			local cf = cam.CFrame
			if UserInputService:IsKeyDown(Enum.KeyCode.W) then dir = dir + cf.LookVector end
			if UserInputService:IsKeyDown(Enum.KeyCode.S) then dir = dir - cf.LookVector end
			if UserInputService:IsKeyDown(Enum.KeyCode.A) then dir = dir - cf.RightVector end
			if UserInputService:IsKeyDown(Enum.KeyCode.D) then dir = dir + cf.RightVector end
			if UserInputService:IsKeyDown(Enum.KeyCode.Space) then dir = dir + Vector3.new(0, 1, 0) end
			if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) or UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then
				dir = dir - Vector3.new(0, 1, 0)
			end
			if dir.Magnitude > 0 then
				dir = dir.Unit * FLY_SPEED
			end
			flyParts[1].Velocity = dir
		end))
		notify("Fly enabled - WASD / Space / Shift")
	else
		if flyConn then flyConn:Disconnect() flyConn = nil end
		if flyParts then
			for _, p in ipairs(flyParts) do pcall(function() p:Destroy() end) end
			flyParts = nil
		end
		notify("Fly disabled")
	end
	return true
end

