--------------------------------------------------------------------------------
--  Player tab
--------------------------------------------------------------------------------

local playerScroll = makeScroll(tabPages["Player"])

local speedOn, jumpOn, noclipOn = false, false, false
local speedVal, jumpVal = 16, 50
local speedSaved, jumpSaved = nil, nil

local function applySpeed()
	local h = getHum()
	if h then h.WalkSpeed = speedVal end
end
local function applyJump()
	local h = getHum()
	if h then
		pcall(function() h.UseJumpPower = true end)
		pcall(function() h.JumpPower = jumpVal end)
	end
end

track(LocalPlayer.CharacterAdded:Connect(function(c)
	c:WaitForChild("Humanoid", 10)
	task.wait(0.3)
	if speedOn then applySpeed() end
	if jumpOn then applyJump() end
end))

makeActionRow(playerScroll, 1, "WalkSpeed", "Sets your character walking speed", {
	value = {
		default = 16, min = 1, max = 2000,
		changed = function(n)
			speedVal = n
			if speedOn then applySpeed() end
		end,
	},
	onToggle = function(state, getVal)
		speedOn = state
		if state then
			speedVal = getVal and getVal() or speedVal
			local h = getHum()
			if h then speedSaved = h.WalkSpeed end
			applySpeed()
			notify("WalkSpeed: " .. tostring(speedVal))
		else
			local h = getHum()
			if h then h.WalkSpeed = speedSaved or 16 end
			notify("WalkSpeed reset")
		end
	end,
})

makeActionRow(playerScroll, 2, "JumpPower", "Sets your character jump height", {
	value = {
		default = 50, min = 1, max = 2000,
		changed = function(n)
			jumpVal = n
			if jumpOn then applyJump() end
		end,
	},
	onToggle = function(state, getVal)
		jumpOn = state
		if state then
			jumpVal = getVal and getVal() or jumpVal
			local h = getHum()
			if h then
				jumpSaved = {}
				pcall(function() jumpSaved.power = h.JumpPower end)
				pcall(function() jumpSaved.height = h.JumpHeight end)
				pcall(function() jumpSaved.use = h.UseJumpPower end)
			end
			applyJump()
			notify("JumpPower: " .. tostring(jumpVal))
		else
			local h = getHum()
			if h and jumpSaved then
				pcall(function() h.UseJumpPower = jumpSaved.use end)
				pcall(function() h.JumpPower = jumpSaved.power end)
				pcall(function() h.JumpHeight = jumpSaved.height end)
			end
			notify("JumpPower reset")
		end
	end,
})

makeActionRow(playerScroll, 3, "Noclip", "Walk through walls and other objects", {
	onToggle = function(state)
		noclipOn = state
		if not state then
			local c = getChar()
			if c then
				for _, p in ipairs(c:GetDescendants()) do
					if p:IsA("BasePart") then p.CanCollide = true end
				end
			end
			notify("Noclip disabled")
		else
			notify("Noclip enabled")
		end
	end,
})

track(RunService.Stepped:Connect(function()
	if not noclipOn then return end
	local c = getChar()
	if not c then return end
	for _, p in ipairs(c:GetDescendants()) do
		if p:IsA("BasePart") then p.CanCollide = false end
	end
end))

